4	import org.springframework.boot.autoconfigure.SpringBootApplication;
5	
6	/**
7	 * 禁飞区域与航线版本审查服务入口。
8	 * 默认使用嵌入式 H2（MODE=MySQL）内存库，启动时自动建表并初始化全局空域版本，
9	 * 不依赖外部 MySQL 或 Docker；数据仅保留在 JVM 生命周期内。
10	 */
11	@SpringBootApplication
12	public class StarterApplication {
13	
14	    /**
15	     * 启动禁飞区航线审查 Web 服务。
16	     */
17	    public static void main(String[] args) {
18	        SpringApplication.run(StarterApplication.class, args);
