package com.example.starter.domain;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.TreeSet;

/**
 * 备降机场窗口容量裁决纯逻辑（不依赖数据库与时钟，便于单元测试）。
 *
 * <p>窗口为 UTC 左闭右开 {@code [start, end)}，两窗口重叠当且仅当
 * {@code a.start < b.end && b.start < a.end}。机场容量按时间轴逐段计数：
 * 新申请加入后，任何时段占用数都不得超过容量。</p>
 *
 * <p>挤出规则（整体挤出，不可只挤出一部分）：</p>
 * <ul>
 *   <li>只能挤出与新窗口重叠、状态仍为未起飞且优先级严格更低的预留；</li>
 *   <li>相同优先级与更高优先级预留绝不能被挤出：一旦某超载时段内存在这样的
 *       不可挤预留，申请直接冲突；</li>
 *   <li>需要挤出时按扫描线贪心选择结束时间最晚的低优先级预留（覆盖后续最多超载时段，
 *       保证挤出数量最小），结果对相同输入确定且可复现；</li>
 *   <li>被选中的预留按其整个窗口整体释放，不存在“只挤出部分重叠航线”。</li>
 * </ul>
 */
public final class DiversionPlanner {

    private DiversionPlanner() {
    }

    /**
     * 一个当前占用容量的预留（仅未起飞预留参与裁决）。
     *
     * @param reservationId 预留标识
     * @param routeId       航线标识
     * @param priority      优先级，数值越大越高
     * @param start         UTC 窗口开始（含），epoch 毫秒
     * @param end           UTC 窗口结束（不含），epoch 毫秒
     */
    public record Occupant(String reservationId, String routeId, int priority,
                           long start, long end) {
    }

    /**
     * 裁决结果。
     *
     * @param conflict          是否必须拒绝申请
     * @param blockingReservationId 冲突时阻挡申请的预留标识（同级/高级/不可挤）；不冲突为 null
     * @param displaced         必须整体挤出的预留（按 reservationId 字典序）；冲突时为空
     */
    public record Plan(boolean conflict, String blockingReservationId, List<Occupant> displaced) {

        static Plan conflict(String blockingReservationId) {
            return new Plan(true, blockingReservationId, List.of());
        }

        static Plan accepted(List<Occupant> displaced) {
            List<Occupant> sorted = new ArrayList<>(displaced);
            sorted.sort(Comparator.comparing(Occupant::reservationId));
            return new Plan(false, null, List.copyOf(sorted));
        }
    }

    /** 扫描线事件：同坐标先处理结束（-1）后处理开始（+1），与左闭右开语义一致。 */
    private record Event(long time, int delta, Occupant occupant) {
    }

    /**
     * 在给定容量与当前占用下，裁决新窗口申请。
     *
     * @param capacity    机场窗口容量，必须为正
     * @param current     当前未起飞占用（调用方保证只含 RESERVED 状态）
     * @param newPriority 新申请优先级
     * @param newStart    新窗口开始（含）
     * @param newEnd      新窗口结束（不含）
     * @return 裁决结果；接受时携带需要整体挤出的预留清单
     */
    public static Plan plan(int capacity, List<Occupant> current,
                            int newPriority, long newStart, long newEnd) {
        if (capacity <= 0 || newStart >= newEnd) {
            throw new IllegalArgumentException("容量必须为正且新窗口必须非退化");
        }
        Occupant incoming = new Occupant("__new__", "__new__", newPriority, newStart, newEnd);

        TreeSet<Event> events = new TreeSet<>(
                Comparator.comparingLong(Event::time).thenComparingInt(e -> e.delta));
        for (Occupant o : current) {
            events.add(new Event(o.start(), 1, o));
            events.add(new Event(o.end(), -1, o));
        }
        events.add(new Event(newStart, 1, incoming));
        events.add(new Event(newEnd, -1, incoming));

        // 当前时间点之后处于活跃状态的占用（已处理完该点全部 start/end 事件）
        List<Occupant> active = new ArrayList<>();
        List<Occupant> marked = new ArrayList<>();
        String blocker = null;

        Long cursor = null;
        for (Event event : events) {
            if (cursor != null && event.time() > cursor) {
                // [cursor, event.time) 内活跃集合恒定；仅在新申请窗口内的时段需要容量
                String segmentBlocker = enforceCapacity(capacity, newPriority, active, marked);
                if (segmentBlocker != null && blocker == null) {
                    blocker = segmentBlocker;
                }
            }
            cursor = event.time();
            if (event.delta() == 1) {
                active.add(event.occupant());
            } else {
                active.remove(event.occupant());
            }
        }
        if (blocker != null) {
            return Plan.conflict(blocker);
        }
        return Plan.accepted(marked);
    }

    /**
     * 检查一个容量恒定的时段：活跃占用中除去新申请自身后不得超过容量。
     * 超载时先判定是否存在不可挤预留（同级/高级，永远不能挤出），
     * 否则贪心挤出结束时间最晚的严格低优先级预留，直到不再超载。
     *
     * @return 导致必然冲突的阻挡预留标识；无冲突返回 null
     */
    private static String enforceCapacity(int capacity, int newPriority,
                                          List<Occupant> activeSegment, List<Occupant> marked) {
        // 新申请自身不占用既存容量，从计数中剔除
        List<Occupant> others = new ArrayList<>();
        for (Occupant o : activeSegment) {
            if (!"__new__".equals(o.reservationId())) {
                others.add(o);
            }
        }
        // 新申请必须处于该时段才会造成压力
        boolean incomingActive = activeSegment.stream()
                .anyMatch(o -> "__new__".equals(o.reservationId()));
        if (!incomingActive) {
            return null;
        }

        String blocker = null;
        while (true) {
            long unblocked = others.stream().filter(o -> !marked.contains(o)).count();
            long blocking = others.stream()
                    .filter(o -> !marked.contains(o))
                    .filter(o -> o.priority() >= newPriority)
                    .count();
            // 该时段总占用 = 未挤出既存 + 新申请 1
            if (unblocked + 1 <= capacity) {
                return blocker;
            }
            // 即使把可挤预留全部挤出仍超载：存在不可挤同级/高级预留，冲突确定
            if (blocking + 1 > capacity) {
                return others.stream()
                        .filter(o -> !marked.contains(o))
                        .filter(o -> o.priority() >= newPriority)
                        .map(Occupant::reservationId)
                        .min(String::compareTo)
                        .orElse(blocker);
            }
            // 记录一个阻挡者用于错误信息（若后续贪心后仍超载会返回它）
            if (blocker == null) {
                blocker = others.stream()
                        .filter(o -> !marked.contains(o))
                        .filter(o -> o.priority() >= newPriority)
                        .map(Occupant::reservationId)
                        .min(String::compareTo)
                        .orElse(null);
            }
            int need = (int) (unblocked + 1 - capacity);
            // 贪心：在本时段活跃、未标记、严格低优先级中选结束最晚者整体挤出
            List<Occupant> candidates = others.stream()
                    .filter(o -> !marked.contains(o))
                    .filter(o -> o.priority() < newPriority)
                    .sorted(Comparator.comparingLong(Occupant::end).reversed()
                            .thenComparing(Occupant::reservationId))
                    .toList();
            for (int i = 0; i < need; i++) {
                if (i >= candidates.size()) {
                    // 可挤预留不足：必然有不可挤预留阻挡
                    return others.stream()
                            .filter(o -> !marked.contains(o))
                            .filter(o -> o.priority() >= newPriority)
                            .map(Occupant::reservationId)
                            .min(String::compareTo)
                            .orElse(blocker);
                }
                marked.add(candidates.get(i));
            }
        }
    }
}

