     * 检查一个容量恒定的时段：活跃占用中除去新申请自身后不得超过容量。
     * 超载时先判定是否存在不可挤预留（同级/高级，永远不能挤出），
     * 否则贪心挤出结束时间最晚的严格低优先级预留，直到不再超载。
     *
     * @return 导致必然冲突的阻挡预留标识；无冲突返回 null
     */
    private static String enforceCapacity(int capacity, int newPriority,
                                          List<Occupant> activeSegment, List<Occupant> marked) {
        // 新申请自身不占用既存容量，从计数中剔除
        List<Occupant> others = new ArrayList<>();
        for (Occupant o : activeSegment) {
            if (!"__new__".equals(o.reservationId())) {
                others.add(o);
            }
        }
        // 新申请必须处于该时段才会造成压力
        boolean incomingActive = activeSegment.stream()
                .anyMatch(o -> "__new__".equals(o.reservationId()));
        if (!incomingActive) {
            return null;
        }

        String blocker = null;
        while (true) {
            long unblocked = others.stream().filter(o -> !marked.contains(o)).count();
            long blocking = others.stream()
                    .filter(o -> !marked.contains(o))
                    .filter(o -> o.priority() >= newPriority)
                    .count();
