                return others.stream()
                        .filter(o -> !marked.contains(o))
                        .filter(o -> o.priority() >= newPriority)
                        .map(Occupant::reservationId)
                        .min(String::compareTo)
                        .orElse(blocker);
            }
            // 记录一个阻挡者用于错误信息（若后续贪心后仍超载会返回它）
            if (blocker == null) {
                blocker = others.stream()
                        .filter(o -> !marked.contains(o))
                        .filter(o -> o.priority() >= newPriority)
                        .map(Occupant::reservationId)
                        .min(String::compareTo)
                        .orElse(null);
            }
            int need = (int) (unblocked + 1 - capacity);
            // 贪心：在本时段活跃、未标记、严格低优先级中选结束最晚者整体挤出
            List<Occupant> candidates = others.stream()
