 * 预留起飞标记请求。已起飞预留释放当前容量且此后不能被挤出；
 * 重复标记同一条预留返回 409。
 *
 * @param reservationId 预留唯一标识
 * @param requestId     写操作全局唯一请求标识，用于幂等重放
 */
public record DepartureRequest(
        @NotBlank @Size(max = 64) String reservationId,
        @NotBlank @Size(max = 64) String requestId) {
}

package com.example.starter.api.dto;

/**
 * 起飞标记结果。
 *
 * @param reservationId 预留标识
 * @param status        操作后状态（DEPARTED）
 */
public record DepartureResult(String reservationId, String status) {
}

package com.example.starter.api.dto;

import java.util.List;

/**
 * 机场时段占用视图。按机场与 UTC 左闭右开查询时段返回当前占用、优先级与
 * 不可变替换链。仅返回与查询时段有重叠的预留。
 *
 * @param airportId 机场标识
 * @param capacity  机场窗口容量
 * @param from      查询时段开始（含），epoch 毫秒（UTC）
 * @param to        查询时段结束（不含），epoch 毫秒（UTC）
 * @param occupancy 与查询时段重叠的占用条目，按窗口开始、预留标识排序
 */
public record OccupancyView(String airportId, int capacity, long from, long to,
                            List<OccupancyEntry> occupancy) {
}

package com.example.starter.api.dto;

import java.util.List;

/**
 * 占用视图中的单条预留。
 *
 * @param reservationId 预留标识
 * @param routeId       航线标识
 * @param priority      优先级，数值越大越高
 * @param windowStart   UTC 窗口开始（含），epoch 毫秒
 * @param windowEnd     UTC 窗口结束（不含），epoch 毫秒
 * @param status        RESERVED / DEPARTED / DISPLACED
 * @param replacedBy    挤出本预留的预留标识；从未被挤出为 null（不可变）
 * @param chain         不可变替换链：从本预留开始，每项为挤出它的预留，按替换先后排序；
 *                      末端预留的 replacedBy 为 null。后续起飞不改写旧替换结果。
 */
public record OccupancyEntry(String reservationId, String routeId, int priority,
                             long windowStart, long windowEnd, String status, String replacedBy,
                             List<ReplacementLink> chain) {
}

package com.example.starter.api.dto;

/**
 * 不可变替换链中的一环：source 预留被 target 预留挤出。
 *
 * @param sourceReservationId 被挤出的预留标识
 * @param targetReservationId 挤出方预留标识
 * @param targetRouteId       挤出方航线标识
 * @param targetPriority      挤出方优先级
 * @param targetStatus        挤出方当前状态（可能已起飞/再被挤出；替换关系本身不可变）
 */
public record ReplacementLink(String sourceReservationId, String targetReservationId,
                              String targetRouteId, int targetPriority, String targetStatus) {
}

