185	            // 持锁状态下读取全部有效禁飞区，与上面的版本号同属一个一致状态
186	            List<ZonePo> activeZones = airspaceRepo.findActiveZones();
187	            Set<String> hits = new TreeSet<>();
188	            for (ZonePo zone : activeZones) {
189	                if (Geometry.polylineHitsRectangle(route.points(),
190	                        zone.xMin(), zone.yMin(), zone.xMax(), zone.yMax())) {
191	                    hits.add(zone.zoneId());
192	                }
193	            }
194	            String conclusion = hits.isEmpty()
195	                    ? ReviewConclusion.CLEAR.name()
196	                    : ReviewConclusion.BLOCKED.name();
197	            String reviewId = "rv_" + UUID.randomUUID();
198	            ReviewPo po = new ReviewPo(reviewId, request.routeId(), route.version(), globalVersion,
199	                    conclusion, new ArrayList<>(hits), List.copyOf(route.points()),
200	                    request.requestId(), nowMillis());
201	            reviewRepo.insertReview(po);
202	            return new MutationResponse(request.requestId(), false, toDto(po, conclusion, true));
203	        });
