227	            boolean current = currentRoute != null
228	                    && currentRoute.version() == latest.routeVersion()
229	                    && globalVersion == latest.airspaceVersion();
230	            // 不匹配时绝不能把旧 CLEAR/BLOCKED 当成当前结论，统一返回 STALE
231	            String conclusion = current ? latest.conclusion() : "STALE";
