236	    // ============================ 幂等与事务 ============================
237	
238	    /**
239	     * 在事务内执行幂等写操作：
240	     * 同键同参返回首次成功结果（标记 replayed=true）；同键异参/异种操作抛 409；
241	     * 业务异常回滚、不占用 requestId；去重记录与业务变更同一事务原子提交。
242	     *
243	     * <p>同键并发时，落败事务可能先撞上唯一约束（DuplicateKeyException），
244	     * 也可能在持锁后读到赢家已提交的状态而抛业务冲突（409）；两种情况都在
245	     * 回滚后用新事务查询去重表：赢家同键同参已提交则重放原结果，否则按原错误抛出。</p>
246	     */
247	    private MutationResponse withIdempotency(String requestId, String kind, String paramHash,
248	                                             Supplier<MutationResponse> action) {
249	        try {
250	            return txTemplate.execute(status -> doIdempotent(requestId, kind, paramHash, action));
251	        } catch (DuplicateKeyException dup) {
252	            return resolveAfterRace(requestId, kind, paramHash,
253	                    new ApiException(HttpStatus.CONFLICT, "RESOURCE_CONFLICT",
254	                            "并发资源冲突，请稍后使用相同 requestId 与参数重试"));
255	        } catch (ApiException api) {
256	            if (api.status() == HttpStatus.CONFLICT) {
257	                return resolveAfterRace(requestId, kind, paramHash, api);
258	            }
259	            throw api;
260	        }
261	    }
262	
263	    /**
264	     * 并发落败后的裁决：去重表中存在同键记录则按重放/异参冲突处理；
265	     * 不存在（说明该 requestId 尚未成功、这是一次真实业务冲突）则抛出原错误，
266	     * 不占用 requestId。
267	     */
268	    private MutationResponse resolveAfterRace(String requestId, String kind, String paramHash,
269	                                              ApiException original) {
270	        DedupPo winner = txTemplate.execute(status -> reviewRepo.findDedup(requestId));
271	        if (winner == null) {
272	            throw original;
273	        }
274	        ensureSameRequest(winner, kind, paramHash);
275	        return deserializeReplay(winner);
276	    }
277	
278	    private MutationResponse doIdempotent(String requestId, String kind, String paramHash,
279	                                          Supplier<MutationResponse> action) {
280	        DedupPo existing = reviewRepo.findDedup(requestId);
281	        if (existing != null) {
282	            ensureSameRequest(existing, kind, paramHash);
283	            return deserializeReplay(existing);
284	        }
285	        // 业务异常会触发事务回滚，去重键不会被占用
286	        MutationResponse result = action.get();
287	        reviewRepo.insertDedup(new DedupPo(requestId, kind, paramHash,
288	                writeJson(result), nowMillis()));
289	        return result;
290	    }
291	
292	    private void ensureSameRequest(DedupPo existing, String kind, String paramHash) {
293	        if (!existing.requestKind().equals(kind) || !existing.requestHash().equals(paramHash)) {
294	            throw new ApiException(HttpStatus.CONFLICT, "IDEMPOTENT_PARAM_MISMATCH",
295	                    "requestId 已用于参数不同的请求: " + existing.requestId());
296	        }
297	    }
298	
299	    private MutationResponse deserializeReplay(DedupPo po) {
300	        try {
301	            MutationResponse original = objectMapper.readValue(po.responseJson(), MutationResponse.class);
302	            // 业务结果原样重放，仅传输标记告知客户端本次为重放
303	            return new MutationResponse(original.requestId(), true, original.data());
304	        } catch (JsonProcessingException ex) {
305	            throw new IllegalStateException("无法解析幂等重放结果: " + po.requestId(), ex);
306	        }
307	    }
308	
309	    // ============================ 工具方法 ============================
310	
311	    private static List<Point> toPoints(List<RoutePointDto> dtos) {
312	        List<Point> points = new ArrayList<>(dtos.size());
313	        for (RoutePointDto dto : dtos) {
314	            points.add(new Point(dto.x(), dto.y()));
315	        }
316	        return points;
317	    }
318	
319	    private static void validatePointsDistinct(List<Point> points) {
320	        Point first = points.get(0);
321	        for (Point p : points) {
322	            if (p.x() != first.x() || p.y() != first.y()) {
323	                return;
324	            }
325	        }
326	        throw new ApiException(HttpStatus.BAD_REQUEST, "ROUTE_POINTS_IDENTICAL",
327	                "航线至少需要两个不同的点");
328	    }
329	
330	    private static ReviewResultDto toDto(ReviewPo po, String conclusion, Boolean current) {
331	        List<RoutePointDto> snapshot = new ArrayList<>(po.pointsSnapshot().size());
332	        for (Point p : po.pointsSnapshot()) {
333	            snapshot.add(new RoutePointDto(p.x(), p.y()));
334	        }
335	        return new ReviewResultDto(po.reviewId(), po.routeId(), po.routeVersion(),
336	                po.airspaceVersion(), conclusion, List.copyOf(po.hitZoneIds()), snapshot, current);
337	    }
338	
339	    private long nowMillis() {
340	        return clock.instant().toEpochMilli();
341	    }
342	
343	    private String writeJson(Object value) {
344	        try {
345	            return objectMapper.writeValueAsString(value);
346	        } catch (JsonProcessingException ex) {
347	            throw new IllegalStateException("响应序列化失败", ex);
348	        }
349	    }
350	
351	    /**
352	     * 计算请求参数的规范化哈希（SHA-256）。
353	     * 对象字段按键名字典序递归排序，列表保持顺序，使相同语义参数产生相同哈希、
354	     * 字段书写顺序不同不影响比对结果。
355	     */
356	    private String canonicalHash(Object request) {
357	        try {
358	            JsonNode sorted = canonicalize(objectMapper.valueToTree(request));
359	            String canonical = objectMapper.writeValueAsString(sorted);
360	            MessageDigest digest = MessageDigest.getInstance("SHA-256");
361	            return HexFormat.of().formatHex(digest.digest(canonical.getBytes(StandardCharsets.UTF_8)));
362	        } catch (JsonProcessingException | NoSuchAlgorithmException ex) {
363	            throw new IllegalStateException("无法计算请求哈希", ex);
364	        }
365	    }
366	
367	    private static JsonNode canonicalize(JsonNode node) {
368	        if (node.isObject()) {
369	            ObjectNode sorted = JsonNodeFactory.instance.objectNode();
370	            List<String> names = new ArrayList<>();
371	            node.fieldNames().forEachRemaining(names::add);
372	            names.sort(String::compareTo);
373	            for (String name : names) {
374	                sorted.set(name, canonicalize(node.get(name)));
375	            }
376	            return sorted;
377	        }
378	        if (node.isArray()) {
379	            ArrayNode array = JsonNodeFactory.instance.arrayNode();
380	            node.forEach(child -> array.add(canonicalize(child)));
381	            return array;
382	        }
383	        return node;
384	    }
385	}
