    @Test
    @DisplayName("幂等：同键同参重放 replayed=true 且挤出清单一致；同键异参409")
    void idempotentReplayOverHttp() throws Exception {
        mockMvc.perform(post("/api/airspace/diversion/airports")
                        .contentType(MediaType.APPLICATION_JSON)
