@DisplayName("409拒绝整体回滚：挤出清单中的预留不会出现部分挤出")
void conflictRollsBackWithoutPartialDisplacement() {
    // 容量 1：一个已起飞低级 D 与一个未起飞低级 L 同窗，
    // 高级申请只能挤 L 但 D 仍阻挡 → 409；L 必须保持 RESERVED
    createAirport("A", 1);
    ReservationResult departed = dataOf(reserve("D", "A", 1, 100, 200));
    ReservationResult movable = dataOf(reserve("L", "A", 1, 0, 300));
    service.depart(new DepartureRequest(departed.reservationId(), reqId("depart-req")));

    ApiException ex = assertThrows(ApiException.class,
            () -> reserve("H", "A", 9, 100, 200));
    assertEquals(HttpStatus.CONFLICT, ex.status());
    assertEquals("RESERVED", reservationRow(movable.reservationId()).get("status"));
    assertNull(reservationRow(movable.reservationId()).get("replaced_by"));
    // 没有写入任何新预留
    assertEquals(2,
            jdbc.queryForObject("SELECT COUNT(*) FROM diversion_reservation", Integer.class));
}

